// Types the export signature names arrive at the crate root via `use`.
// The types those reference (but that the world does not `use`) stay in the
// package module.
use crate::aap::caps::types::{Category, ClassifiedItem, DroppedItem, Importance};

use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

/// Percent-encode a string for use in a URL query value.
///
/// The feed item's fields are `Untrusted<FeedItem>` — adversarial free text.
/// Before any of it crosses into a URL we encode everything outside the
/// unreserved set, so the item's text is carried strictly as a query *value*
/// and cannot steer the request's structure (no path, host, or parameter
/// injection from attacker-controlled bytes).
fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                let hex = b"0123456789ABCDEF";
                out.push(hex[(b >> 4) as usize] as char);
                out.push(hex[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

fn parse_category(s: &str) -> Category {
    let s = s.to_ascii_lowercase();
    if s.contains("security") {
        Category::Security
    } else if s.contains("release") {
        Category::Release
    } else if s.contains("research") {
        Category::Research
    } else if s.contains("tooling") {
        Category::Tooling
    } else if s.contains("discussion") {
        Category::Discussion
    } else {
        Category::Other
    }
}

fn parse_importance(s: &str) -> Importance {
    let s = s.to_ascii_lowercase();
    if s.contains("must") {
        Importance::MustRead
    } else if s.contains("skip") {
        Importance::Skip
    } else {
        Importance::WorthALook
    }
}

impl Guest for Node {
    fn run(item: FeedItem) -> Classification {
        // Enrichment lookup for this item. The response is not folded into the
        // node's output: the classification below is a pure function of the
        // item and the model's verdict. The untrusted item text is encoded as a
        // query value before it reaches the URL (see `percent_encode`). The
        // http-client handle's host allowlist is enforced at the boundary; a
        // host outside it traps rather than returning here.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&item.text)
        );
        let _ = http_client::fetch(&url);

        // Classify. `LLMClient<inference>` offers only `infer` and returns a
        // string: the node can be influenced by the model but cannot act on it.
        let system = "You are a triage classifier for a software and security \
                      news feed. Reply with exactly two lowercase words: a \
                      category — one of release, security, research, tooling, \
                      discussion, other — and an importance — one of must-read, \
                      worth-a-look, skip. No other text.";
        let prompt = format!(
            "Title: {}\nFeed: {}\nLink: {}\nPublished: {}\nText: {}",
            item.title, item.feed, item.link, item.published, item.text
        );
        let verdict = inference_llm::infer(system, &prompt, "classify");

        let category = parse_category(&verdict);
        let importance = parse_importance(&verdict);

        // The closed `importance` set does the routing: `skip` is dropped, the
        // other two are kept. Trust is discharged by producing the typed
        // ClassifiedItem / DroppedItem.
        match importance {
            Importance::Skip => Classification::Drop(DroppedItem { item, category }),
            _ => Classification::Keep(ClassifiedItem {
                item,
                category,
                importance,
            }),
        }
    }
}

export!(Node);
